{
  "name": "opencode-worktree-guard",
  "version": "0.3.7",
  "description": "OpenCode plugin to enforce Git worktree discipline - one session, one worktree",
  "type": "module",
  "main": "dist/index.js",
  "module": "dist/index.js",
  "exports": {
    ".": "./dist/index.js"
  },
  "files": [
    "dist/",
    "src/",
    "scripts/",
    "README.md"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target node",
    "dev": "bun build src/index.ts --outdir dist --target node --watch",
    "prepublishOnly": "bun run build",
    "postinstall": "node scripts/postinstall.cjs"
  },
  "keywords": [
    "opencode",
    "plugin",
    "git",
    "worktree",
    "guard"
  ],
  "author": "chuck-ma",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/chuck-ma/opencode-config.git"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.1.36"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.1.53"
  },
  "publishConfig": {
    "registry": "https://registry.npmjs.org/"
  }
}
